// Realms: the Quake 2 client effects (realms::GameEffects, cl_fx.c /
// cl_tent.c / cl_ents.c) without a game module: byte directions, temp
// entities, muzzle flashes, entity trails and lights, explosions (with
// .md2 models generated by md2_builder.h), lasers, the particle budget and
// the sounds the effects start.
#include "md2_builder.h"

#include "realms/Engine.h"
#include "realms/GameEffects.h"
#include "realms/GameSound.h"
#include "realms/GameView.h"
#include "realms/q2game.h"

#include <chrono>
#include <cmath>
#include <cstdio>
#include <filesystem>
#include <fstream>
#include <string>
#include <vector>

namespace {

int gChecks = 0, gFailures = 0;

#define CHECK(cond)                                                                                                \
    do {                                                                                                           \
        ++gChecks;                                                                                                 \
        if (!(cond)) {                                                                                             \
            ++gFailures;                                                                                           \
            std::fprintf(stderr, "  FAIL %s:%d: %s\n", __FILE__, __LINE__, #cond);                                 \
        }                                                                                                          \
    } while (0)

bool near(float a, float b, float eps) { return std::fabs(a - b) <= eps; }
float dist(const std::array<float, 3> &a, const std::array<float, 3> &b) {
    const float x = a[0] - b[0], y = a[1] - b[1], z = a[2] - b[2];
    return std::sqrt(x * x + y * y + z * z);
}

realms::GameEvent tent(int type, std::array<float, 3> pos) {
    realms::GameEvent ev;
    ev.kind = realms::GameEvent::Kind::TempEntity;
    ev.level = type;
    ev.origin = pos;
    ev.dir = {0, 0, 1};
    return ev;
}

bool hasSound(const std::vector<realms::GameEvent> &sounds, const std::string &name) {
    for (const auto &s : sounds)
        if (s.kind == realms::GameEvent::Kind::Sound && s.text == name) return true;
    return false;
}

void byteDirChecks() {
    int bad = 0;
    for (int i = 0; i < 162; i++) {
        const realms::Vec3 d = realms::gameByteDir(i);
        const float len = std::sqrt(d[0] * d[0] + d[1] * d[1] + d[2] * d[2]);
        if (!near(len, 1.0f, 2e-3f) || realms::gameDirToByte(d.data()) != i) bad++;
    }
    CHECK(bad == 0);
    const float up[3] = {0, 0, 1}, down[3] = {0, 0, -1};
    CHECK(realms::gameByteDir(realms::gameDirToByte(up))[2] > 0.99f);
    CHECK(realms::gameByteDir(realms::gameDirToByte(down))[2] < -0.99f);
    CHECK(realms::gameDirToByte(nullptr) == 0);
    const realms::Vec3 none = realms::gameByteDir(162);
    CHECK(none[0] == 0 && none[1] == 0 && none[2] == 0);
}

void tempEntityChecks() {
    realms::GameEffects fx;
    std::vector<realms::GameParticle> parts;
    std::vector<realms::GameDynamicLight> lights;
    std::vector<realms::GameEffectModel> models;

    // a rocket explosion: the poly explosion model, its light, 256 particles, the sound
    const std::array<float, 3> at{100, 200, 50};
    fx.handleEvent(tent(realms::GTE_ROCKET_EXPLOSION, at), 1000);
    CHECK(fx.particleCount() == 256);
    CHECK(fx.explosionCount() == 1);
    fx.models(1000, models);
    CHECK(models.size() == 1 && models[0].model == "models/objects/r_explode/tris.md2");
    if (!models.empty()) {
        CHECK(models[0].fullbright && (models[0].oldframe == 0 || models[0].oldframe == 15));
        CHECK(models[0].frame == models[0].oldframe + 1 && models[0].skinnum == 0);
    }
    fx.lights(1000, lights);
    CHECK(lights.size() == 1 && near(lights[0].radius, 350, 1e-3f) && near(lights[0].color[1], 0.5f, 1e-6f));
    fx.models(1250, models); // frame 2: skin 1, light fading
    CHECK(models.size() == 1 && models[0].skinnum == 1 && near(models[0].backlerp, 0.5f, 1e-3f));
    fx.lights(1250, lights);
    CHECK(lights.size() == 1 && near(lights[0].radius, 350 * 14 / 16.0f, 1e-2f));
    fx.models(2150, models); // past frame 10: translucent, skin 5 / 6
    CHECK(models.size() == 1 && (models[0].skinnum == 5 || models[0].skinnum == 6) && models[0].alpha < 0.4f);
    fx.update(2500); // 15 frames: gone after 1.4 s
    CHECK(fx.explosionCount() == 0);
    CHECK(fx.particleCount() == 0); // alphavel -0.8 / (0.5..0.8): faded after 1 s
    const auto sounds = fx.takeSounds();
    CHECK(hasSound(sounds, "sound/weapons/rocklx1a.wav"));
    CHECK(fx.takeSounds().empty());

    // particles start where the effect is and fall with gravity
    fx.reset();
    fx.handleEvent(tent(realms::GTE_EXPLOSION1_NP, at), 0); // no particles
    CHECK(fx.particleCount() == 0 && fx.explosionCount() == 1);
    fx.reset();
    fx.handleEvent(tent(realms::GTE_BLOOD, at), 0);
    CHECK(fx.particleCount() == 60);
    fx.particles(0, parts);
    bool inside = parts.size() == 60;
    for (const auto &p : parts) inside &= dist(p.origin, at) < 4 * 1.8f + 31 && p.color[3] == 1.0f && p.size == 1.0f;
    CHECK(inside);
    std::vector<realms::GameParticle> later;
    fx.particles(300, later);
    float drop = 0;
    for (size_t i = 0; i < later.size() && i < parts.size(); i++) drop += parts[i].origin[2] - later[i].origin[2];
    CHECK(later.size() == 60 && drop / 60 > 0.0f); // gravity 40 * t^2 beats crand * 20 * t on average
    CHECK(later[0].color[3] < 1.0f);

    // the palette: blood is red (approximate colormap), or the real one
    CHECK(!fx.realPalette());
    const auto red = fx.paletteColor(0xe8);
    CHECK(red[0] > red[1] && red[0] > red[2]);
    std::vector<uint8_t> pal(768);
    for (int i = 0; i < 256; i++) pal[size_t(i * 3)] = pal[size_t(i * 3 + 1)] = pal[size_t(i * 3 + 2)] = uint8_t(i);
    fx.setPalette(pal.data());
    CHECK(fx.realPalette() && near(fx.paletteColor(128)[1], 128 / 255.0f, 1e-6f));
    fx.setPalette(nullptr);
    CHECK(!fx.realPalette());

    // blaster impact: 40 particles, the translucent fullbright explode model, a yellow light
    fx.reset();
    auto blaster = tent(realms::GTE_BLASTER, at);
    blaster.dir = {1, 0, 0};
    fx.handleEvent(blaster, 0);
    CHECK(fx.particleCount() == 40);
    fx.models(0, models);
    CHECK(models.size() == 1 && models[0].model == "models/objects/explode/tris.md2" && models[0].fullbright);
    if (!models.empty()) CHECK(near(models[0].angles[0], 90, 1e-3f) && near(models[0].angles[1], 0, 1e-3f));
    fx.models(150, models);
    CHECK(models.size() == 1 && near(models[0].alpha, 0.5f, 1e-3f));
    fx.lights(0, lights);
    CHECK(lights.size() == 1 && near(lights[0].radius, 150, 1e-3f) && lights[0].color[2] == 0.0f);
    CHECK(hasSound(fx.takeSounds(), "sound/weapons/lashit.wav"));

    // gunshot: puffs, smoke and a flash
    fx.reset();
    fx.handleEvent(tent(realms::GTE_GUNSHOT, at), 0);
    CHECK(fx.particleCount() == 40 && fx.explosionCount() == 2);
    fx.models(0, models);
    CHECK(models.size() == 2);
    fx.models(120, models); // the flash lasts one frame
    CHECK(models.size() == 1 && models[0].model == "models/objects/smoke/tris.md2");

    // splash: palette by type, sparks sound
    fx.reset();
    auto splash = tent(realms::GTE_SPLASH, at);
    splash.count = 8;
    splash.color = realms::GSPLASH_BLUE_WATER;
    fx.handleEvent(splash, 0);
    CHECK(fx.particleCount() == 8);
    splash.color = 99; // bad splash type: colour 0, no crash
    fx.handleEvent(splash, 0);
    CHECK(fx.particleCount() == 16);

    // rail: the spiral (one per unit) and the core (one per 0.75)
    fx.reset();
    auto rail = tent(realms::GTE_RAILTRAIL, {0, 0, 0});
    rail.end = {300, 0, 0};
    fx.handleEvent(rail, 0);
    CHECK(fx.particleCount() == 300 + 400);
    fx.particles(0, parts);
    bool spiral = true;
    for (size_t i = 0; i < 300 && i < parts.size(); i++)
        spiral &= near(std::hypot(parts[i].origin[1], parts[i].origin[2]), 3.0f, 1e-3f);
    CHECK(spiral);
    CHECK(hasSound(fx.takeSounds(), "sound/weapons/railgf1a.wav"));

    // BFG laser: a beam for 100 ms
    fx.reset();
    auto laser = tent(realms::GTE_BFG_LASER, {0, 0, 0});
    laser.end = {0, 100, 0};
    fx.handleEvent(laser, 0);
    std::vector<realms::GameBeam> beams;
    fx.beams(50, beams);
    CHECK(beams.size() == 1 && near(beams[0].end[1], 100, 1e-6f) && near(beams[0].color[3], 0.3f, 1e-6f));
    CHECK(beams.size() == 1 && beams[0].color[1] > beams[0].color[0]); // greens 0xd0..0xd3
    fx.beams(150, beams);
    CHECK(beams.empty());

    // parasite cable: model segments 30 units apart
    fx.reset();
    auto cable = tent(realms::GTE_PARASITE_ATTACK, {0, 0, 0});
    cable.entity = 7;
    cable.end = {95, 0, 0};
    fx.handleEvent(cable, 0);
    fx.models(100, models);
    CHECK(models.size() == 4 && models[0].model == "models/monsters/parasite/segment/tris.md2");
    if (models.size() == 4) CHECK(near(models[3].origin[0], 90, 1e-3f) && near(models[0].angles[1], 0, 1e-3f));
    cable.end = {0, 0, 40}; // replaces entity 7's beam
    fx.handleEvent(cable, 50);
    fx.models(100, models);
    CHECK(models.size() == 2);
    if (!models.empty()) CHECK(near(models[0].angles[0], 90, 1e-3f));
    fx.models(300, models);
    CHECK(models.empty());

    // the budget: MAX_PARTICLES, the rest dropped
    fx.reset();
    fx.handleEvent(tent(realms::GTE_BOSSTPORT, at), 0);
    fx.handleEvent(tent(realms::GTE_ROCKET_EXPLOSION, at), 0);
    CHECK(int(fx.particleCount()) == realms::GameEffects::kMaxParticles);
    CHECK(fx.droppedParticles() >= 1);

    // nonsense in, nothing out
    fx.reset();
    fx.handleEvent(tent(9999, at), 0);
    fx.handleEvent(tent(-1, at), 0);
    fx.handleEvent(tent(realms::GTE_BLOOD, {std::nanf(""), 0, 0}), 0);
    auto huge = tent(realms::GTE_RAILTRAIL, {0, 0, 0});
    huge.end = {1e30f, 0, 0};
    fx.handleEvent(huge, 0);
    CHECK(int(fx.particleCount()) <= realms::GameEffects::kMaxParticles && fx.explosionCount() == 0);
}

void muzzleFlashChecks() {
    realms::GameEffects fx;
    std::vector<realms::GameDynamicLight> lights;
    // the player's: 18 forward and 16 right of the entity, gone after 50 ms
    realms::GameEvent mz;
    mz.kind = realms::GameEvent::Kind::MuzzleFlash;
    mz.entity = 1;
    mz.level = realms::GMZ_RAILGUN;
    mz.origin = {0, 0, 0};
    mz.angles = {0, 90, 0}; // facing +y: right is +x
    fx.handleEvent(mz, 0);
    fx.lights(10, lights);
    CHECK(lights.size() == 1);
    if (!lights.empty()) {
        CHECK(near(lights[0].origin[0], 16, 1e-3f) && near(lights[0].origin[1], 18, 1e-3f));
        CHECK(lights[0].radius >= 200 && lights[0].radius < 232 && near(lights[0].color[2], 1, 1e-6f));
    }
    fx.lights(60, lights);
    CHECK(lights.empty());
    CHECK(hasSound(fx.takeSounds(), "sound/weapons/railgf1a.wav"));
    // a second flash from the same entity reuses its light
    fx.handleEvent(mz, 100);
    fx.handleEvent(mz, 110);
    CHECK(fx.dlightCount(120) == 1);
    CHECK(fx.takeSounds().size() == 2);
    // silenced: smaller, quieter
    mz.level = realms::GMZ_MACHINEGUN | realms::GMZ_SILENCED;
    fx.handleEvent(mz, 200);
    fx.lights(200, lights);
    CHECK(lights.size() == 1 && lights[0].radius < 132);
    auto sounds = fx.takeSounds();
    CHECK(sounds.size() == 1 && sounds[0].volume < 0.5f && sounds[0].text.find("sound/weapons/machgf") == 0);
    // the shotgun's reload click comes 0.1 s later
    mz.level = realms::GMZ_SHOTGUN;
    fx.handleEvent(mz, 300);
    sounds = fx.takeSounds();
    CHECK(sounds.size() == 2 && sounds[1].text == "sound/weapons/shotgr1b.wav" && near(sounds[1].delay, 0.1f, 1e-6f));
    // login: 500 green particles and a one-second light
    fx.reset();
    mz.level = realms::GMZ_LOGIN;
    fx.handleEvent(mz, 0);
    CHECK(fx.particleCount() == 500 && fx.dlightCount(900) == 1);

    // a monster's (MZ2_TANK_BLASTER_1): the table's offset rotated by the angles
    fx.reset();
    realms::GameEvent m2 = mz;
    m2.level = 1000 + 1;
    m2.entity = 5;
    m2.origin = {100, 100, 0};
    fx.handleEvent(m2, 0);
    fx.lights(0, lights);
    CHECK(lights.size() == 1);
    if (!lights.empty()) {
        CHECK(near(lights[0].origin[0], 100 - 18.5f, 1e-3f) && near(lights[0].origin[1], 100 + 20.7f, 1e-3f));
        CHECK(near(lights[0].origin[2], 28.7f, 1e-3f));
    }
    sounds = fx.takeSounds();
    CHECK(sounds.size() == 1 && sounds[0].text == "sound/tank/tnkatck3.wav" && sounds[0].entity == 5);
    // the tank's machine gun: a puff, smoke, "tnkatk2a".."e"
    m2.level = 1000 + 4;
    fx.handleEvent(m2, 0);
    CHECK(fx.particleCount() == 40 && fx.explosionCount() == 2);
    sounds = fx.takeSounds();
    CHECK(sounds.size() == 1 && sounds[0].text.size() == std::string("sound/tank/tnkatk2a.wav").size() &&
          sounds[0].text.compare(0, 18, "sound/tank/tnkatk2") == 0 && sounds[0].text[18] >= 'a' &&
          sounds[0].text[18] <= 'e');
    // unused / out of range numbers
    m2.level = 1000 + 0;
    fx.handleEvent(m2, 0);
    m2.level = 1000 + 500;
    fx.handleEvent(m2, 0);
    CHECK(fx.takeSounds().empty());
}

void entityEffectChecks() {
    realms::GameEffects fx;
    std::vector<realms::GameDynamicLight> lights;
    std::vector<realms::GameParticle> parts;
    realms::GameRenderEntity rocket;
    rocket.number = 12;
    rocket.modelindex = 3;
    rocket.model = "models/objects/rocket/tris.md2";
    rocket.effects = Q2_EF_ROCKET;
    realms::GameLerpedEntity l;
    l.entity = &rocket;
    // a rocket flying +x: smoke and fire between the frames, a light on it
    double t = 0;
    for (int i = 0; i <= 10; i++, t += 16) {
        l.origin = {float(i * 10), 0, 0};
        fx.addEntityEffects({l}, i / 6, t);
        fx.update(t);
    }
    CHECK(fx.particleCount() > 20);
    fx.particles(t, parts);
    bool along = !parts.empty();
    for (const auto &p : parts) along &= p.origin[0] > -40 && p.origin[0] < 140;
    CHECK(along);
    fx.lights(t, lights);
    CHECK(lights.size() == 1 && near(lights[0].radius, 200, 1e-6f) && near(lights[0].origin[0], 100, 1e-6f));
    // the light is per frame: no entity, no light
    fx.addEntityEffects({}, 3, t + 16);
    fx.lights(t + 16, lights);
    CHECK(lights.empty());

    // a new entity starts its trail at old_origin (when it is close)
    fx.reset();
    rocket.oldOrigin = {0, 0, 0};
    l.origin = {200, 0, 0};
    fx.addEntityEffects({l}, 0, 0);
    const size_t fromOld = fx.particleCount();
    CHECK(fromOld > 50);
    fx.reset();
    rocket.oldOrigin = {0, 0, 0};
    l.origin = {2000, 0, 0}; // too far: teleported, no trail
    fx.addEntityEffects({l}, 0, 0);
    CHECK(fx.particleCount() == 0);

    // a gib: the blood trail thins out
    fx.reset();
    realms::GameRenderEntity gib;
    gib.number = 20;
    gib.modelindex = 4;
    gib.model = "models/objects/gibs/sm_meat/tris.md2";
    gib.effects = Q2_EF_GIB;
    l.entity = &gib;
    std::vector<size_t> added;
    for (int i = 0; i < 40; i++) {
        l.origin = {float(i * 20), 0, 0};
        const size_t before = fx.particleCount();
        fx.addEntityEffects({l}, i, i * 100.0);
        added.push_back(fx.particleCount() - before);
        fx.update(i * 100.0);
    }
    CHECK(added[1] > 20 && added[39] < added[1]);
    // BFG: 162 one-frame particles, a green light; sprites are glows
    fx.reset();
    realms::GameRenderEntity bfg;
    bfg.number = 30;
    bfg.modelindex = 5;
    bfg.model = "sprites/s_bfg1.sp2";
    bfg.effects = Q2_EF_BFG | Q2_EF_ANIM_ALLFAST;
    l.entity = &bfg;
    l.origin = {0, 0, 0};
    fx.addEntityEffects({l}, 0, 500);
    CHECK(fx.particleCount() == 162);
    fx.particles(500, parts);
    CHECK(parts.size() == 163 && parts.back().size > 1.0f && parts.back().color[1] > parts.back().color[0]);
    fx.lights(500, lights);
    CHECK(lights.size() == 1 && lights[0].color[1] == 1.0f && lights[0].color[0] == 0.0f);
    fx.update(520);
    CHECK(fx.particleCount() == 0);
    // teleporter pads spit particles once per server frame
    fx.reset();
    realms::GameRenderEntity pad;
    pad.number = 40;
    pad.modelindex = 6;
    pad.model = "models/objects/dmspot/tris.md2";
    pad.effects = Q2_EF_TELEPORTER;
    l.entity = &pad;
    fx.addEntityEffects({l}, 7, 0);
    fx.addEntityEffects({l}, 7, 16);
    CHECK(fx.particleCount() == 8);
    fx.addEntityEffects({l}, 8, 100);
    CHECK(fx.particleCount() == 16);

    // entity events: item respawn and teleports
    fx.reset();
    realms::GameEvent ev;
    ev.kind = realms::GameEvent::Kind::EntityEvent;
    ev.level = realms::GEV_ITEM_RESPAWN;
    fx.handleEvent(ev, 0);
    CHECK(fx.particleCount() == 64);
    ev.level = realms::GEV_PLAYER_TELEPORT;
    fx.handleEvent(ev, 0);
    CHECK(fx.particleCount() == 64 + 9 * 9 * 13);
    ev.level = realms::GEV_FOOTSTEP; // sound only (from the server)
    fx.handleEvent(ev, 0);
    CHECK(fx.particleCount() == 64 + 9 * 9 * 13);

    // laser entities (RF_BEAM): from origin to old_origin, frame = width
    fx.reset();
    realms::GameBeamEntity beam;
    beam.origin = {0, 0, 0};
    beam.oldOrigin = {0, 0, 64};
    beam.frame = 4;
    beam.skinnum = int(0xf2f2f0f0u);
    fx.setBeamEntities({beam});
    std::vector<realms::GameBeam> beams;
    fx.beams(0, beams);
    CHECK(beams.size() == 1 && near(beams[0].width, 4, 1e-6f) && near(beams[0].end[2], 64, 1e-6f));
}

void sceneChecks() {
    namespace fs = std::filesystem;
    const fs::path tmp = fs::temp_directory_path() /
                         ("realms-effects-test-" + std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));
    std::error_code ec;
    fs::create_directories(tmp / "models/objects/r_explode", ec);
    // a 30-frame stand-in for the explosion model, with 7 skins
    std::vector<std::pair<std::array<float, 3>, std::array<float, 3>>> boxes;
    for (int i = 0; i < 30; i++) boxes.push_back({{-float(i), -8, -8}, {float(i), 8, 8}});
    auto def = md2_builder::boxModel(boxes);
    def.skins.clear();
    for (int i = 0; i < 7; i++) def.skins.push_back("models/objects/r_explode/skin" + std::to_string(i) + ".pcx");
    const auto bytes = md2_builder::writeMd2(def);
    std::ofstream(tmp / "models/objects/r_explode/tris.md2", std::ios::binary)
        .write(reinterpret_cast<const char *>(bytes.data()), std::streamsize(bytes.size()));

    realms::EngineConfig cfg;
    cfg.backend = realms::BackendPreference::Native;
    cfg.searchRoots = {tmp.string()};
    realms::Engine engine;
    CHECK(engine.init(cfg));
    realms::GameEffects fx;
    std::string perr;
    CHECK(!fx.loadPalette(engine, &perr) && !perr.empty() && !fx.realPalette()); // no colormap.pcx: approximation

    fx.handleEvent(tent(realms::GTE_ROCKET_EXPLOSION, {10, 20, 30}), 0);
    fx.handleEvent(tent(realms::GTE_BLASTER, {0, 0, 0}), 0); // explode/tris.md2 is missing: skipped
    std::vector<realms::GameEffectModel> models;
    fx.models(250, models);
    CHECK(models.size() == 2);
    realms::GameModelCache cache;
    realms::GameScene scene;
    realms::appendEffectModels(engine, cache, models, scene);
    CHECK(scene.batches.size() == 1);
    if (!scene.batches.empty()) {
        const auto &b = scene.batches[0];
        CHECK(b.model == "models/objects/r_explode/tris.md2" && b.effect && b.fullbright);
        CHECK(b.skin == "models/objects/r_explode/skin1.pcx");
        CHECK(b.count == 36 && near(b.origin[2], 30, 1e-6f) && near(b.color[3], 1.0f, 1e-6f));
        CHECK(near(b.angles[0], 0, 1e-6f));
    }
    fs::remove_all(tmp, ec);
}

std::vector<uint8_t> wav(int channels, int bits, int rate, const std::vector<int> &samples, int cue = -1) {
    std::vector<uint8_t> b;
    auto u32 = [&](uint32_t v) {
        for (int i = 0; i < 4; i++) b.push_back(uint8_t(v >> (8 * i)));
    };
    auto u16 = [&](int v) {
        b.push_back(uint8_t(v & 0xff));
        b.push_back(uint8_t((v >> 8) & 0xff));
    };
    auto tag = [&](const char *t) { b.insert(b.end(), t, t + 4); };
    const uint32_t dataBytes = uint32_t(samples.size()) * uint32_t(bits / 8);
    tag("RIFF");
    u32(0); // patched below
    tag("WAVE");
    tag("fmt ");
    u32(16);
    u16(1);
    u16(channels);
    u32(uint32_t(rate));
    u32(uint32_t(rate * channels * bits / 8));
    u16(channels * bits / 8);
    u16(bits);
    if (cue >= 0) {
        tag("cue ");
        u32(28);
        u32(1);
        for (int i = 0; i < 6; i++) u32(i == 5 ? uint32_t(cue) : 0); // id .. sampleOffset
    }
    tag("data");
    u32(dataBytes);
    for (int v : samples) {
        if (bits == 8) b.push_back(uint8_t(v));
        else u16(v);
    }
    if (dataBytes & 1) b.push_back(0);
    const uint32_t riff = uint32_t(b.size() - 8);
    for (int i = 0; i < 4; i++) b[size_t(4 + i)] = uint8_t(riff >> (8 * i));
    return b;
}

void soundChecks() {
    // .wav: 8-bit unsigned and 16-bit signed, mono / stereo, cue loop points
    realms::GameWav w;
    std::string err;
    auto b8 = wav(1, 8, 11025, {128, 255, 0, 64, 192});
    CHECK(realms::decodeGameWav(b8.data(), b8.size(), w, &err));
    CHECK(w.rate == 11025 && w.channels == 1 && w.frames() == 5 && w.loopStart == -1);
    CHECK(w.samples.size() == 5 && w.samples[0] == 0 && w.samples[1] == 127 * 256 && w.samples[2] == -32768);
    auto b16 = wav(2, 16, 22050, {1000, -1000, 32767, -32768}, 1);
    CHECK(realms::decodeGameWav(b16.data(), b16.size(), w, &err));
    CHECK(w.channels == 2 && w.frames() == 2 && w.samples[1] == -1000 && w.samples[3] == -32768 && w.loopStart == 1);
    auto bad = b16;
    bad[20] = 3; // IEEE float
    CHECK(!realms::decodeGameWav(bad.data(), bad.size(), w, &err) && err.find("PCM") != std::string::npos);
    CHECK(!realms::decodeGameWav(b16.data(), 11, w, &err));
    CHECK(!realms::decodeGameWav(nullptr, 0, w, &err));
    auto cut = b16;
    cut.resize(cut.size() - 4); // the data chunk says more than there is: what's there plays
    CHECK(realms::decodeGameWav(cut.data(), cut.size(), w, &err) && w.frames() == 1);
    auto big = wav(1, 16, 22050, {1, 2}, 99); // cue past the end: no loop point
    CHECK(realms::decodeGameWav(big.data(), big.size(), w, &err) && w.loopStart == -1);

    // S_SpatializeOrigin
    realms::GameListener ear;
    ear.origin = {0, 0, 0};
    ear.right = realms::gameRightVector({0, 0, 0}); // facing +x: right is -y
    CHECK(near(ear.right[1], -1, 1e-6f));
    ear.entity = 1;
    auto s = realms::gameSpatialize({50, 0, 0}, 0, 1.0f, 1.0f, ear);
    CHECK(near(s.volume, 1, 1e-6f) && near(s.pan, 0, 1e-6f)); // within 80 units
    s = realms::gameSpatialize({0, -1080, 0}, 0, 1.0f, 1.0f, ear);
    CHECK(near(s.volume, 0.5f, 1e-4f) && near(s.pan, 1, 1e-5f)); // (1080 - 80) * 0.0005, on the right
    s = realms::gameSpatialize({0, 80 + 500 / 3.0f, 0}, 0, 1.0f, 3.0f, ear); // ATTN_STATIC: 3 * 0.001
    CHECK(near(s.volume, 0.5f, 1e-4f) && s.pan < -0.99f);
    s = realms::gameSpatialize({5000, 0, 0}, 0, 1.0f, 1.0f, ear);
    CHECK(s.volume == 0.0f);
    s = realms::gameSpatialize({5000, 0, 0}, 0, 0.7f, 0.0f, ear); // ATTN_NONE
    CHECK(near(s.volume, 0.7f, 1e-6f) && s.pan == 0.0f);
    s = realms::gameSpatialize({0, -1080, 0}, 1, 1.0f, 1.0f, ear); // the player's own
    CHECK(near(s.volume, 1, 1e-6f) && s.pan == 0.0f);
    s = realms::gameSpatialize({std::nanf(""), 0, 0}, 0, 2.0f, 1.0f, ear);
    CHECK(s.volume == 1.0f && s.pan == 0.0f);

    // timeofs: delayed sounds wait; order is kept
    realms::GameSoundScheduler q;
    realms::GameEvent ev;
    ev.kind = realms::GameEvent::Kind::Sound;
    ev.text = "sound/weapons/shotgr1b.wav";
    ev.delay = 0.1f;
    ev.level = Q2_CHAN_AUTO;
    q.push(ev, 1000);
    ev.text = "sound/weapons/shotgf1b.wav";
    ev.delay = 0.0f;
    ev.level = Q2_CHAN_WEAPON | 8; // flags above the channel are dropped
    ev.entity = 1;
    q.push(ev, 1000);
    realms::GameEvent print;
    q.push(print, 1000); // not a sound
    CHECK(q.pending() == 2);
    std::vector<realms::GameSoundPlay> due;
    q.due(1050, ear, due);
    CHECK(due.size() == 1 && due[0].name == "sound/weapons/shotgf1b.wav" && due[0].channel == Q2_CHAN_WEAPON &&
          due[0].spatial.volume == 1.0f);
    q.due(1101, ear, due); // 0.1f s
    CHECK(due.size() == 1 && due[0].name == "sound/weapons/shotgr1b.wav" && q.pending() == 0);
    for (size_t i = 0; i < realms::GameSoundScheduler::kMaxPending + 10; i++) q.push(ev, 0);
    CHECK(q.pending() == realms::GameSoundScheduler::kMaxPending);
    q.clear();

    // loops: the same sound from several entities is one voice, summed
    std::vector<realms::GameLoopSound> loops(3);
    loops[0] = {5, "sound/world/fire1.wav", {0, -100, 0}};
    loops[1] = {6, "sound/world/fire1.wav", {0, -100, 0}};
    loops[2] = {7, "sound/world/amb10.wav", {0, 100, 0}};
    std::vector<realms::GameSoundPlay> merged;
    realms::GameSoundScheduler::mergeLoops(loops, ear, merged);
    CHECK(merged.size() == 2);
    if (merged.size() == 2) {
        const float one = 1.0f - 20 * 0.003f;
        CHECK(merged[0].name == "sound/world/fire1.wav" && near(merged[0].spatial.volume, std::min(2 * one, 1.0f), 1e-4f));
        CHECK(merged[0].spatial.pan > 0.99f && merged[1].spatial.pan < -0.99f && near(merged[1].spatial.volume, one, 1e-4f));
    }
    loops[2].origin = {0, 5000, 0}; // out of earshot
    realms::GameSoundScheduler::mergeLoops(loops, ear, merged);
    CHECK(merged.size() == 1);
}

} // namespace

int main() {
    soundChecks();
    byteDirChecks();
    tempEntityChecks();
    muzzleFlashChecks();
    entityEffectChecks();
    sceneChecks();
    std::printf("[effects] %d checks, %d failures\n", gChecks, gFailures);
    return gFailures == 0 ? 0 : 1;
}
